INSERT INTO `projects` (`id`, `title`, `sub_title`, `description`, `image_url`, `demo_url`, `github_url`, `created_at`, `updated_at`, `category`, `tech_tags`, `architecture_steps`) VALUES (3,'Entok Monitoring','Platform operasional peternakan dengan telemetri timbangan dan dashboard realtime.','Sistem full-stack untuk memantau operasional peternakan entok. Repository menggabungkan dashboard Next.js, REST API Flask, MySQL, komunikasi realtime, firmware ESP32, serta alur data timbangan dan batch pemberian pakan.','/static/uploads/projects/entok-monitoring.svg',NULL,'https://github.com/Marshel2727/entok-monitoring','2026-06-08 06:11:00','2026-07-10 16:07:17','IoT System','[\"Next.js\", \"TypeScript\", \"Flask\", \"MySQL\", \"ESP32\", \"WebSocket\", \"Docker Compose\"]','[{\"label\": \"01\", \"title\": \"Device Telemetry\", \"description\": \"ESP32 dan modul timbangan mengirim pembacaan sensor serta data batch pakan ke endpoint backend.\"}, {\"label\": \"02\", \"title\": \"Operational API\", \"description\": \"Flask menangani validasi, aturan bisnis, autentikasi, migrasi, dan penyimpanan MySQL.\"}, {\"label\": \"03\", \"title\": \"Realtime Delivery\", \"description\": \"Socket.IO menyebarkan pembaruan operasional ke dashboard tanpa menunggu refresh manual.\"}, {\"label\": \"04\", \"title\": \"Web Dashboard\", \"description\": \"Next.js menyajikan dashboard, portal penjaga, dan website publik dalam satu frontend.\"}]'),(4,'Mars AI Local','Asisten AI privat berbasis Ollama dengan chat multi-user dan peringkas WhatsApp.','Asisten AI local-first yang menjalankan model melalui Ollama agar percakapan tetap berada di komputer pengguna. Arsitekturnya menghubungkan Next.js, FastAPI, MySQL, dan microservice WhatsApp berbasis Node.js dalam lingkungan Docker Compose.','/static/uploads/projects/mars-ai-local.svg',NULL,'https://github.com/Marshel2727/mars-web-ai-local','2026-07-23 03:16:19','2026-07-23 07:40:12','AI Application','[\"Next.js\", \"FastAPI\", \"Ollama\", \"MySQL\", \"Node.js\", \"Docker Compose\"]','[{\"label\": \"01\", \"title\": \"User Experience\", \"description\": \"Next.js menyediakan autentikasi, sesi chat, serta antarmuka ringkasan pesan.\"}, {\"label\": \"02\", \"title\": \"Application API\", \"description\": \"FastAPI mengelola konteks percakapan, identitas pengguna, dan komunikasi database.\"}, {\"label\": \"03\", \"title\": \"Local Inference\", \"description\": \"Ollama menjalankan model lokal sehingga isi percakapan tidak perlu dikirim ke layanan model cloud.\"}, {\"label\": \"04\", \"title\": \"WhatsApp Service\", \"description\": \"Microservice Node.js mengambil pesan yang diizinkan lalu meneruskannya untuk diringkas oleh AI.\"}]'),(5,'Mars Web Translator AI','Penerjemah dokumentasi teknis langsung di browser dengan model AI lokal.','Ekstensi Chrome/Brave yang menerjemahkan teks halaman ke Bahasa Indonesia melalui FastAPI dan Ollama. Sistem memprioritaskan teks yang terlihat, melanjutkan antrean di latar belakang, menjaga istilah teknis, dan menyimpan hasil berulang di cache browser.','/static/uploads/projects/mars-web-translator-ai.svg',NULL,'https://github.com/Marshel2727/mars-web-translator-ai','2026-06-15 08:49:24','2026-07-26 13:31:25','AI Application','[\"Manifest V3\", \"JavaScript\", \"FastAPI\", \"Ollama\", \"Qwen 2.5\", \"Pydantic\"]','[{\"label\": \"01\", \"title\": \"Viewport Scanner\", \"description\": \"Content script memindai node teks dan mendahulukan konten yang sedang terlihat oleh pengguna.\"}, {\"label\": \"02\", \"title\": \"Batch Translation API\", \"description\": \"Ekstensi mengirim kumpulan teks ke FastAPI melalui endpoint terstruktur.\"}, {\"label\": \"03\", \"title\": \"Local Model\", \"description\": \"Model Qwen khusus di Ollama menerjemahkan tanpa mengubah kode, URL, perintah, atau nama paket.\"}, {\"label\": \"04\", \"title\": \"DOM Restore & Cache\", \"description\": \"Hasil ditulis kembali ke halaman dan disimpan di chrome.storage.local untuk pemakaian ulang.\"}]'),(6,'Mars MCP Backend Analyzer','MCP read-only untuk memetakan backend Python dengan konteks yang hemat token.','Analyzer lokal yang mengekspos tool kecil dan terarah untuk merencanakan analisis, memetakan project, memilih file relevan, membuat outline, mencari kode, dan membaca rentang baris secara aman tanpa mengirim seluruh repository ke model.','/static/uploads/projects/mars-mcp-backend-analyzer.svg',NULL,'https://github.com/Marshel2727/Mars-MCP-backend-analyzer','2026-07-08 17:16:17','2026-07-08 17:35:50','Developer Tool','[\"Python\", \"MCP\", \"CLI\", \"AST\", \"Pytest\", \"Ollama\"]','[{\"label\": \"01\", \"title\": \"Plan\", \"description\": \"Tool planner menentukan kedalaman dan langkah analisis berdasarkan pertanyaan pengguna.\"}, {\"label\": \"02\", \"title\": \"Compact Map\", \"description\": \"Scanner membangun brief, struktur file, dan simbol penting sambil menghormati ignore rules.\"}, {\"label\": \"03\", \"title\": \"Relevant Context\", \"description\": \"Pencarian memilih file dan baris yang paling berkaitan dengan tugas saat ini.\"}, {\"label\": \"04\", \"title\": \"Safe Read\", \"description\": \"Proteksi path traversal dan pemblokiran file sensitif menjaga analyzer tetap read-only.\"}]'),(7,'Mars MCP Git Publisher','Tool MCP untuk preview, commit, dan push Git dengan guard rails.','Server MCP Python yang menyederhanakan workflow publikasi Git menjadi satu tool terjaga. Sebelum commit dan push, sistem melakukan safety check terhadap repository, branch aktif, perubahan, dan target remote agar operasi tetap eksplisit dan mudah diaudit.','/static/uploads/projects/mars-mcp-git-publisher.svg',NULL,'https://github.com/Marshel2727/mars-MCP-push-github','2026-07-11 19:24:03','2026-07-12 06:22:27','Developer Tool','[\"Python\", \"MCP\", \"Git\", \"Pytest\", \"Ruff\"]','[{\"label\": \"01\", \"title\": \"Repository Preview\", \"description\": \"Tool membaca branch, remote, dan perubahan untuk menetapkan cakupan publikasi.\"}, {\"label\": \"02\", \"title\": \"Guarded Commit\", \"description\": \"Safety checks dijalankan sebelum membuat commit dengan pesan yang diberikan pengguna.\"}, {\"label\": \"03\", \"title\": \"Branch-aware Push\", \"description\": \"Commit dipublikasikan ke origin pada branch aktif tanpa mengganti riwayat secara paksa.\"}]'),(8,'Mars Face — AuraReader','Eksperimen vision AI untuk analisis ekspresi dan ramalan hiburan dari webcam.','Aplikasi Next.js yang mengambil foto dari webcam, mengompres gambar di browser, lalu mengirimkannya melalui Server Action ke model vision DigitalOcean. Hasil HTML dibersihkan dengan DOMPurify dan ditampilkan dengan efek typewriter serta penanganan error yang jelas.','/static/uploads/projects/mars-face.png','https://mars-face.vercel.app','https://github.com/Marshel2727/mars-face','2026-04-29 10:10:39','2026-05-14 08:14:47','AI Application','[\"Next.js\", \"React\", \"JavaScript\", \"React Webcam\", \"Vision AI\", \"DOMPurify\"]','[{\"label\": \"01\", \"title\": \"Camera Capture\", \"description\": \"React Webcam menangkap wajah dengan rasio adaptif dan kompresi JPEG di canvas.\"}, {\"label\": \"02\", \"title\": \"Server Action\", \"description\": \"Foto dan request ID diteruskan ke server agar kunci layanan AI tidak berada di browser.\"}, {\"label\": \"03\", \"title\": \"Vision Inference\", \"description\": \"Model vision menghasilkan analisis hiburan dalam struktur HTML yang dibatasi oleh prompt keselamatan.\"}, {\"label\": \"04\", \"title\": \"Safe Presentation\", \"description\": \"DOMPurify menyaring respons sebelum hasil ditampilkan secara bertahap pada antarmuka.\"}]'),(9,'Mars Buket Backend','REST API e-commerce buket untuk katalog, alamat, autentikasi, dan pesanan.','Backend modular berbasis Flask untuk aplikasi penjualan buket. Struktur repository memisahkan model, route, schema, service, dan utility, dengan dukungan JWT, SQLAlchemy, MySQL, serta migrasi Alembic untuk alur produk dan pesanan.','/static/uploads/projects/mars-buket.svg',NULL,'https://github.com/Marshel2727/mars-buket','2026-05-21 11:27:34','2026-05-22 14:23:02','Backend API','[\"Python\", \"Flask\", \"MySQL\", \"SQLAlchemy\", \"JWT\", \"Alembic\"]','[{\"label\": \"01\", \"title\": \"Resource Routes\", \"description\": \"Blueprint memisahkan endpoint autentikasi, produk, alamat, dan pesanan.\"}, {\"label\": \"02\", \"title\": \"Service Layer\", \"description\": \"Aturan bisnis diletakkan di service agar route tetap tipis dan mudah dirawat.\"}, {\"label\": \"03\", \"title\": \"Relational Data\", \"description\": \"SQLAlchemy memodelkan data dan Alembic menjaga perubahan skema database.\"}, {\"label\": \"04\", \"title\": \"Protected Access\", \"description\": \"JWT melindungi operasi pengguna dan alur transaksi yang memerlukan identitas.\"}]'),(10,'Mars Portfolio','Portfolio full-stack dengan CMS admin, studi kasus, dan deployment Docker.','Portfolio utama yang menggabungkan frontend Next.js, backend Flask, MySQL, autentikasi admin, manajemen project dan skill, galeri, pesan kontak, serta konten halaman yang dapat diedit dari panel admin. Deployment lokal disatukan melalui Docker Compose dan Nginx.','/static/uploads/projects/mars-portfolio.png','https://mars-porto.vercel.app','https://github.com/Marshel2727/mars_porto','2026-04-04 00:48:04','2026-07-12 10:25:25','Web Application','[\"Next.js\", \"TypeScript\", \"Flask\", \"MySQL\", \"Docker Compose\", \"Nginx\", \"JWT\"]','[{\"label\": \"01\", \"title\": \"Public Experience\", \"description\": \"Next.js menyajikan profil, katalog project, detail studi kasus, skill, resume, dan kontak.\"}, {\"label\": \"02\", \"title\": \"Admin CMS\", \"description\": \"Panel terlindungi mengelola project, skill, galeri, profil, pesan, dan seluruh copy halaman publik.\"}, {\"label\": \"03\", \"title\": \"Flask API\", \"description\": \"Service backend menangani validasi, autentikasi JWT, upload, dan kontrak data frontend.\"}, {\"label\": \"04\", \"title\": \"Container Delivery\", \"description\": \"Nginx mengarahkan trafik ke frontend dan backend yang berjalan bersama MySQL melalui Docker Compose.\"}]'),(11,'Culiner Foods','Katalog kuliner responsif dengan detail menu berbasis data JSON.','Website katalog makanan berbasis HTML, CSS, dan JavaScript. Data menu dimuat dari JSON lokal, dirender menjadi kartu visual, lalu diteruskan ke halaman detail menggunakan parameter ID pada URL.','/static/uploads/projects/culiner-foods.png','https://culiner-foods.vercel.app','https://github.com/Marshel2727/culiner-foods','2026-02-19 10:04:40','2026-04-07 00:34:40','Web Application','[\"HTML\", \"CSS\", \"JavaScript\", \"JSON\", \"Vercel\"]','[{\"label\": \"01\", \"title\": \"Local Catalog Data\", \"description\": \"Data menu, harga, kalori, porsi, dan gambar disimpan dalam berkas JSON.\"}, {\"label\": \"02\", \"title\": \"Dynamic Cards\", \"description\": \"JavaScript membaca JSON dan membangun kartu menu beserta statistiknya di DOM.\"}, {\"label\": \"03\", \"title\": \"Detail Navigation\", \"description\": \"ID menu diteruskan melalui query string untuk menampilkan data item pada halaman detail.\"}]'),(12,'Katalog Audio','Katalog perangkat audio interaktif dengan spesifikasi produk berbasis JSON.','Website katalog perangkat audio yang menampilkan produk, warna, bobot, latensi, baterai, dan harga. JavaScript menghasilkan kartu produk dari JSON lokal dan membuka halaman detail berdasarkan ID item.','/static/uploads/projects/katalog-audio.png','https://katalog-audio-ten.vercel.app','https://github.com/Marshel2727/katalog-audio','2026-01-20 10:22:35','2026-02-11 15:20:13','Web Application','[\"HTML\", \"CSS\", \"JavaScript\", \"JSON\", \"Vercel\"]','[{\"label\": \"01\", \"title\": \"Product Dataset\", \"description\": \"Spesifikasi perangkat audio dan referensi gambar dikelola dalam satu dataset JSON.\"}, {\"label\": \"02\", \"title\": \"Catalog Rendering\", \"description\": \"JavaScript membuat kartu produk dan menampilkan atribut teknis langsung di halaman utama.\"}, {\"label\": \"03\", \"title\": \"Item Detail\", \"description\": \"Halaman detail membaca parameter ID untuk memilih produk yang diminta pengguna.\"}]');
